prompt --application/shared_components/user_interface/lovs/nonemployeesinfo_idpessoa
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(49938221397605999184)
,p_lov_name=>'NONEMPLOYEESINFO-IDPESSOA'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH all_involved_ids AS (',
'    SELECT idPessoa FROM Compete',
'    UNION',
'    SELECT idPessoa FROM Trabalham',
'    UNION',
'    SELECT idPessoa FROM Juri',
')',
'SELECT',
'    p.nomePessoa || '' - '' || p.dataNascimento || '' - '' || p.nacionalidade AS info,',
'    p.idPessoa AS idp',
'FROM',
'    Pessoas p',
'WHERE',
'    p.idPessoa IN (',
'        SELECT idPessoa FROM Pessoas',
'        MINUS',
'        SELECT idPessoa FROM all_involved_ids',
'    );'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'IDP'
,p_display_column_name=>'INFO'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
,p_version_scn=>15627643922096
);
end;
