'WITH all_involved_ids AS (',
'    SELECT idPessoa FROM Compete',
'    UNION',
'    SELECT idPessoa FROM Trabalham',
'    UNION',
'    SELECT idPessoa FROM Juri',
')',
'SELECT',
'    p.nomePessoa || '' - '' || p.dataNascimento || '' - '' || p.nacionalidade AS info,',
'    p.idPessoa AS idp',
'FROM',
'    Pessoas p',
'WHERE',
'    p.idPessoa IN (',
'        SELECT idPessoa FROM Pessoas',
'        MINUS',
