,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH PontosPorEquipa AS (',
'    SELECT',
'        CMP.nomeEquipa,',
'        SUM(TDP.pontos) AS total_pontos,',
'        RANK() OVER (ORDER BY SUM(TDP.pontos) DESC) AS ranking_pontos',
'    FROM Compete C',
'    JOIN TabelaDePontos TDP ON C.posicao = TDP.posicao',
'    JOIN Competidores CMP ON C.idPessoa = CMP.idPessoa',
'    GROUP BY CMP.nomeEquipa',
')',
'SELECT',
'    nomeEquipa,',
'    total_pontos',
'FROM PontosPorEquipa',
'WHERE ranking_pontos = 1;'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
